<script lang="ts">
import {useLocale} from '$lib/i18n';import Language from '$lib/components/Language.svelte';import {post} from '$lib/api';import {goto} from '$app/navigation';import {ArrowRight,Building2,Check} from 'lucide-svelte';
const {t,get}=useLocale();let name=$state(''),industry=$state(''),description=$state(''),language=$state(get()),starter=$state(true),busy=$state(false),error=$state('');
async function submit(e:SubmitEvent){e.preventDefault();busy=true;error='';try{const {id}=await post('workspaces',{name,industry,description,website:'',language,timezone:'Asia/Jakarta',autonomous:true,paused:false});if(starter){for(const [agent,role,avatar] of [['Aria','Business Coordinator','blue'],['Maya','Marketing Specialist','purple'],['Raka','Sales Specialist','green']])await post(`workspaces/${id}/entities`,{kind:'agent',data:{name:agent,role,avatar,status:'active',instructions:`You are a ${role}. Use only supplied company information. State uncertainty clearly. Deliver actionable work in the company language.`}});}await goto('/dashboard',{invalidateAll:true});}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="onboarding"><header><a class="brand dark" href="/dashboard"><img src="/favicon.svg" alt=""/><div>ORVEXA<small>Your AI Workforce.</small></div></a><Language/></header><div class="onboard-grid"><div><span class="eyebrow">YOUR COMPANY, CONNECTED</span><h1>{t('Kenalkan bisnis Anda.','Introduce your business.')}<br/><em>{t('Tim Anda mulai di sini.','Your team starts here.')}</em></h1><p>{t('Setiap bisnis punya cerita. Beri tim AI Anda konteks untuk membantu dengan tepat.','Every business has a story. Give your AI team the context to help you better.')}</p><div class="onboard-steps"><div><span>01</span><strong>{t('Profil perusahaan','Company profile')}</strong></div><div><span>02</span><strong>{t('Ajarkan tentang bisnis','Share your knowledge')}</strong></div><div><span>03</span><strong>{t('Mulai bekerja bersama','Start working together')}</strong></div></div><p class="subtle">{t('Workspace terpisah untuk setiap perusahaan. Anda bisa menambahkan perusahaan lain nanti.','A separate workspace for every company. You can add another company later.')}</p></div><form class="card onboarding-form" onsubmit={submit}><div class="section-heading"><Building2 size={22}/><h2>{t('Perusahaan Anda','Your company')}</h2></div>{#if error}<div class="alert error">{error}</div>{/if}<label>{t('Nama perusahaan / usaha','Company / business name')}<input required minlength="2" maxlength="120" bind:value={name} placeholder="Nusantara Studio"/></label><label>{t('Bidang usaha','Industry')}<input required maxlength="120" bind:value={industry} placeholder={t('Contoh: jasa desain, kuliner, retail','e.g. design services, food, retail')}/></label><label>{t('Ceritakan bisnis Anda','Tell us about your business')}<textarea rows="4" maxlength="6000" bind:value={description} placeholder={t('Apa yang Anda tawarkan dan siapa pelanggan Anda?','What do you offer, and who are your customers?')}></textarea></label><label>{t('Bahasa kerja tim AI','AI team working language')}<select bind:value={language}><option value="id">Bahasa Indonesia</option><option value="en">English</option></select></label><label class="checkbox-row"><input type="checkbox" bind:checked={starter}/><span><strong>{t('Siapkan tim awal untuk saya','Set up my starter team')}</strong><small>{t('Coordinator, Marketing, dan Sales. Bisa Anda ubah kapan saja.','Coordinator, Marketing, and Sales. Customize them anytime.')}</small></span></label><button class="primary full" disabled={busy}>{busy?t('Menyiapkan workspace…','Setting up your workspace…'):t('Buat workspace','Create workspace')}<ArrowRight size={17}/></button></form></div></div>
